        if t_idx < len(text) and p_idx < len(pattern) and (pattern[p_idx] == text[t_idx] or pattern[p_idx] == '.'):
            return dfs(p_idx + 1, t_idx + 1)

        if p_idx + 1 < len(pattern) and pattern[p_idx + 1] == '*':
